15	/// Full attention layer weights (8 layers in Qwen3.5-4B).
16	pub(crate) struct FullAttentionLayer {
17	    /// Q projection including gate: [num_heads * head_dim * 2, hidden_size]
18	    pub(crate) q_proj: DeviceMatrix,
19	    /// K projection: [num_kv_heads * head_dim, hidden_size]
20	    pub(crate) k_proj: DeviceMatrix,
21	    /// V projection: [num_kv_heads * head_dim, hidden_size]
22	    pub(crate) v_proj: DeviceMatrix,
23	    /// Output projection: [hidden_size, num_heads * head_dim]
24	    pub(crate) o_proj: DeviceMatrix,
25	    /// QK norm weights: [head_dim] (broadcast to all heads)
26	    pub(crate) q_norm: DeviceVec,
27	    pub(crate) k_norm: DeviceVec,
28	}
29	
30	/// Linear attention layer weights (24 layers in Qwen3.5-4B).
31	pub(crate) struct LinearAttentionLayer {
32	    /// Fused qkv+z projection: [local_linear_qkv_dim + local_linear_z_dim,
33	    /// hidden_size]; rows [0, local_linear_qkv_dim) follow
34	    /// `linear_qkv_shard_segments`, the rows above them are z.
35	    pub(crate) in_proj_qkvz: DeviceMatrix,
36	    /// Fused beta+alpha projection: [2 * local_linear_num_value_heads,
37	    /// hidden_size]; beta occupies rows [0, local_linear_num_value_heads) and
38	    /// alpha the rows above them.
39	    pub(crate) in_proj_ba: DeviceMatrix,
40	    /// Depthwise conv1d weight: [local_linear_qkv_dim * conv_kernel_dim]
41	    /// (flattened from [qkv_dim, 1, 4]); channel layout mirrors the qkv band of
42	    /// `in_proj_qkvz`.
43	    pub(crate) conv1d_weight: DeviceVec,
44	    /// dt_bias: [local_linear_num_value_heads] bf16
45	    pub(crate) dt_bias: DeviceVec,
46	    /// A_log: [local_linear_num_value_heads] f32 (a bf16-stored vector is
47	    /// widened exactly at load — see `tensor_f32_cow`)
48	    pub(crate) a_log: CudaSlice<f32>,
49	    /// RMSNorm weight for output normalization: [value_head_dim] f32 (same
50	    /// loader as `a_log`) — head-shared, so replicated on every rank.
51	    pub(crate) norm_weight: CudaSlice<f32>,
52	    /// Output projection: [hidden_size, local_linear_z_dim] (row-parallel;
53	    /// the layer all-reduces the partial hidden sum under TP).
54	    pub(crate) out_proj: DeviceMatrix,
55	}
