103	/// Transformer block for Qwen3.5.
104	pub(crate) struct TransformerBlock35 {
105	    pub(crate) input_layernorm: DeviceVec,
106	    pub(crate) attn: LayerKind,
107	    pub(crate) post_attention_layernorm: DeviceVec,
