147	
148	impl LinearAttentionLayer {
149	    fn load(src: &WeightSource, prefix: &str) -> Result<Self> {
150	        // Qwen3.5 ships the four projections separately and vLLM fuses them at
151	        // load time into `in_proj_qkvz` and `in_proj_ba`; the same fusion here
152	        // means one GEMM per group instead of four launches.
153	        let qkv = src.linear_in_proj_qkv(&format!("{prefix}.in_proj_qkv.weight"))?;
154	        let z = src.row_shard_if_needed(&format!("{prefix}.in_proj_z.weight"), src.linear_z)?;
155	        let in_proj_qkvz = DeviceMatrix::vstack(src.ctx, &[&qkv, &z])?;
156	        drop(qkv);
157	        drop(z);
158	        let beta = src.row_shard_if_needed(
159	            &format!("{prefix}.in_proj_b.weight"),
160	            src.linear_value_heads,
161	        )?;
162	        let alpha = src.row_shard_if_needed(
163	            &format!("{prefix}.in_proj_a.weight"),
164	            src.linear_value_heads,
165	        )?;
166	        let in_proj_ba = DeviceMatrix::vstack(src.ctx, &[&beta, &alpha])?;
167	        drop(beta);
168	        drop(alpha);
169	        Ok(Self {
170	            in_proj_qkvz,
171	            in_proj_ba,
172	            conv1d_weight: src.linear_conv1d(&format!("{prefix}.conv1d.weight"))?,
173	            dt_bias: src
174	                .tensor_1d_shard_if_needed(&format!("{prefix}.dt_bias"), src.linear_value_heads)?,
175	            a_log: src.tensor_1d_f32_shard_if_needed(
176	                &format!("{prefix}.A_log"),
177	                src.linear_value_heads,
178	            )?,
179	            norm_weight: load_tensor_1d_f32(
180	                src.ctx,
181	                src.shards,
182	                src.weight_map,
183	                &format!("{prefix}.norm.weight"),
184	            )?,
185	            out_proj: src
186	                .col_shard_if_needed(&format!("{prefix}.out_proj.weight"), src.linear_z)?,
187	        })
188	    }
189	}
