191	/// One config-derived extent this rank owns, paired with the full extent it was
192	/// cut from. The sharded loads assert the checkpoint's global shape before
193	/// slicing, so range and global are built together and a call site cannot pair
194	/// one extent's range with another's global.
195	#[derive(Clone, Copy)]
196	struct Shard {
197	    /// `(offset, len)` this rank owns.
198	    range: (usize, usize),
199	    /// The pre-shard extent from `config.json`.
200	    global: usize,
201	}
202	
203	impl Shard {
204	    /// A flat shard of `global` rows (or columns) across the TP ranks.
205	    fn flat(global: usize, geometry: LocalGeometry) -> Self {
206	        Self {
207	            range: geometry.shard_range(global),
208	            global,
209	        }
210	    }
211	}
212	
213	/// The fused linear-attention qkv projection shard: this rank's row slice
214	/// inside each of the three global segments, plus the fused global row count.
215	#[derive(Clone, Copy)]
216	struct LinearQkvShard {
217	    segments: [(usize, usize); 3],
218	    global: usize,
219	}
220	
221	/// One model load's tensor source plus the loop-invariant TP shard ranges the
222	/// per-layer loaders consume. Construct once per load; every loader names only
223	/// the tensor it wants.
224	pub(super) struct WeightSource<'a> {
225	    ctx: &'a DeviceContext,
226	    shards: &'a [SafeTensors<'a>],
227	    weight_map: &'a HashMap<String, usize>,
228	    geometry: LocalGeometry,
229	    /// Model width every unsharded projection must carry, so a checkpoint whose
230	    /// tensors disagree with its `config.json` stops at the loader instead of
231	    /// reaching a GEMM sized from the config.
232	    hidden: usize,
233	    /// Full-attention q_proj rows as per-head [q, gate] chunks.
234	    gated_q: Shard,
235	    /// o_proj column shard over the full-attention q dim.
236	    q_cols: Shard,
237	    /// k/v_proj row shard.
238	    kv_rows: Shard,
239	    /// MLP intermediate row (gate/up) and column (down) shard.
240	    intermediate: Shard,
241	    /// Linear-attention value-head unit: in_proj_b/a rows, dt_bias, A_log.
242	    linear_value_heads: Shard,
243	    /// Linear-attention z dim: in_proj_z rows and out_proj columns.
244	    linear_z: Shard,
245	    /// Per-segment row slices inside the fused linear qkv projection.
246	    linear_qkv: LinearQkvShard,
247	    /// The same slices in conv1d channel-tap units.
248	    linear_conv1d: [(usize, usize); 3],
249	}
250	
251	impl<'a> WeightSource<'a> {
252	    pub(super) fn new(
253	        ctx: &'a DeviceContext,
254	        shards: &'a [SafeTensors<'a>],
255	        weight_map: &'a HashMap<String, usize>,
256	        config: &Config35,
257	        geometry: LocalGeometry,
258	    ) -> Self {
259	        let linear_qkv = linear_qkv_shard(config, geometry);
260	        Self {
261	            ctx,
262	            shards,
263	            weight_map,
264	            geometry,
265	            hidden: config.hidden_size,
266	            gated_q: full_attention_gated_q_shard(config, geometry),
267	            q_cols: Shard::flat(config.full_attn_q_dim(), geometry),
268	            kv_rows: Shard::flat(config.full_attn_kv_dim(), geometry),
269	            intermediate: Shard::flat(config.intermediate_size, geometry),
270	            linear_value_heads: Shard::flat(config.linear_num_value_heads, geometry),
271	            linear_z: Shard::flat(config.linear_attn_z_dim(), geometry),
272	            linear_qkv,
273	            linear_conv1d: conv1d_shard_segments(linear_qkv, config.linear_conv_kernel_dim),
274	        }
275	    }
276	
277	    pub(super) fn tensor_2d(&self, name: &str, rows: usize, cols: usize) -> Result<DeviceMatrix> {
278	        load_tensor_2d(self.ctx, self.shards, self.weight_map, name, rows, cols)
279	    }
280	
281	    pub(super) fn tensor_1d(&self, name: &str) -> Result<DeviceVec> {
282	        load_tensor_1d(self.ctx, self.shards, self.weight_map, name)
283	    }
284	
285	    fn row_shard_if_needed(&self, name: &str, shard: Shard) -> Result<DeviceMatrix> {
286	        if self.geometry.is_sharded() {
287	            let (row_offset, rows) = shard.range;
288	            load_tensor_2d_row_shard(
289	                self.ctx,
290	                self.shards,
291	                self.weight_map,
292	                name,
293	                row_offset,
294	                rows,
295	                (shard.global, self.hidden),
296	            )
297	        } else {
298	            self.tensor_2d(name, shard.global, self.hidden)
299	        }
300	    }
301	
302	    fn col_shard_if_needed(&self, name: &str, shard: Shard) -> Result<DeviceMatrix> {
303	        if self.geometry.is_sharded() {
304	            let (col_offset, cols) = shard.range;
305	            load_tensor_2d_col_shard(
306	                self.ctx,
307	                self.shards,
308	                self.weight_map,
309	                name,
310	                col_offset,
311	                cols,
312	                (self.hidden, shard.global),
313	            )
314	        } else {
315	            self.tensor_2d(name, self.hidden, shard.global)
316	        }
317	    }
318	
319	    fn tensor_1d_shard_if_needed(&self, name: &str, shard: Shard) -> Result<DeviceVec> {
320	        if self.geometry.is_sharded() {
321	            load_tensor_1d_stitch(self.ctx, self.shards, self.weight_map, name, &[shard.range])
322	        } else {
323	            self.tensor_1d(name)
324	        }
325	    }
326	
327	    fn tensor_1d_f32_shard_if_needed(&self, name: &str, shard: Shard) -> Result<CudaSlice<f32>> {
328	        let (offset, len) = shard.range;
329	        if self.geometry.is_sharded() {
330	            load_tensor_1d_f32_shard(self.ctx, self.shards, self.weight_map, name, offset, len)
331	        } else {
332	            load_tensor_1d_f32(self.ctx, self.shards, self.weight_map, name)
333	        }
334	    }
335	
336	    /// Fused linear qkv: stitch this rank's head-local slice out of each of the
337	    /// three global segments rather than cutting one flat row range.
338	    fn linear_in_proj_qkv(&self, name: &str) -> Result<DeviceMatrix> {
339	        if !self.geometry.is_sharded() {
340	            return self.tensor_2d(name, self.linear_qkv.global, self.hidden);
341	        }
342	        load_tensor_2d_row_stitch(
343	            self.ctx,
344	            self.shards,
345	            self.weight_map,
346	            name,
347	            &self.linear_qkv.segments,
348	            (self.linear_qkv.global, self.hidden),
349	        )
350	    }
351	
352	    /// conv1d channels mirror the fused qkv rows, so they stitch with the same
353	    /// segments scaled into kernel-tap units.
354	    fn linear_conv1d(&self, name: &str) -> Result<DeviceVec> {
355	        if !self.geometry.is_sharded() {
356	            return self.tensor_1d(name);
357	        }
358	        load_tensor_1d_stitch(
359	            self.ctx,
360	            self.shards,
361	            self.weight_map,
362	            name,
363	            &self.linear_conv1d,
364	        )
365	    }
366	
367	    /// Q projection carries a per-head output gate, so its rows shard per head
368	    /// (keeping each head's [q, gate] chunk adjacent), not as one flat range.
369	    fn gated_q_proj(&self, name: &str) -> Result<DeviceMatrix> {
370	        if !self.geometry.is_sharded() {
371	            return self.tensor_2d(name, self.gated_q.global, self.hidden);
372	        }
373	        let (row_offset, rows) = self.gated_q.range;
374	        load_tensor_2d_row_shard(
375	            self.ctx,
376	            self.shards,
377	            self.weight_map,
378	            name,
379	            row_offset,
380	            rows,
381	            (self.gated_q.global, self.hidden),
382	        )
383	    }
384	}
385	
386	/// Row ranges this rank owns inside the fused global linear-attention qkv
387	/// projection, with the fused global row count the load asserts against. The
388	/// checkpoint stores [all q rows | all k rows | all v rows]; each segment
389	/// contributes its head-local slice so the rank's stitched rows stay
390	/// [q_local | k_local | v_local]. Never reblock across segments — q rows key on
391	/// key heads, v rows on value heads (the gated-q lesson).
392	fn linear_qkv_shard(config: &Config35, geometry: LocalGeometry) -> LinearQkvShard {
393	    let global_q = config.linear_num_key_heads * config.linear_key_head_dim;
394	    let global_k = global_q;
395	    let global_v = config.linear_attn_z_dim();
396	    let (q_rel, q_rows) = geometry.shard_range(global_q);
397	    let (k_rel, k_rows) = geometry.shard_range(global_k);
398	    let (v_rel, v_rows) = geometry.shard_range(global_v);
399	    LinearQkvShard {
400	        segments: [
401	            (q_rel, q_rows),
402	            (global_q + k_rel, k_rows),
403	            (global_q + global_k + v_rel, v_rows),
404	        ],
405	        global: global_q + global_k + global_v,
406	    }
407	}
408	
409	/// The flattened conv1d weight keeps each channel's kernel taps contiguous
410	/// ([channel, 1, kernel_dim]); its channel layout mirrors the fused qkv rows,
411	/// so shard it with the same per-segment ranges scaled by the kernel dim.
412	fn conv1d_shard_segments(qkv: LinearQkvShard, kernel_dim: usize) -> [(usize, usize); 3] {
413	    qkv.segments
414	        .map(|(offset, len)| (offset * kernel_dim, len * kernel_dim))
415	}
416	
417	/// HF/PegaInfer kernels interpret q_proj rows as per-head [q, gate] chunks:
418	/// every head contributes `head_dim` q rows followed by `head_dim` gate rows.
419	/// Keep each local head's q rows adjacent to its gate rows, so the shard is a
420	/// per-head range rather than a flat cut of the fused rows.
421	fn full_attention_gated_q_shard(config: &Config35, geometry: LocalGeometry) -> Shard {
422	    let gated_rows = |heads: usize| heads * config.head_dim * 2;
423	    let local_heads = geometry.local_num_attention_heads();
424	    Shard {
425	        range: (
426	            gated_rows(geometry.rank() * local_heads),
427	            gated_rows(local_heads),
428	        ),
429	        global: gated_rows(config.num_attention_heads),
430	    }
431	}
432	
433	#[cfg(test)]
434	mod tests {
435	    use super::*;
436	
437	    fn test_config() -> Config35 {
438	        let dir = tempfile::tempdir().unwrap();
439	        std::fs::write(
440	            dir.path().join("config.json"),
441	            r#"{
442	  "max_position_embeddings": 262144,
443	  "tie_word_embeddings": true,
444	  "text_config": {
445	    "hidden_size": 2560,
446	    "intermediate_size": 9216,
447	    "num_hidden_layers": 1,
448	    "num_attention_heads": 16,
449	    "num_key_value_heads": 4,
450	    "head_dim": 256,
451	    "vocab_size": 248320,
452	    "rms_norm_eps": 1e-6,
453	    "layer_types": ["linear_attention"],
454	    "linear_conv_kernel_dim": 4,
455	    "linear_key_head_dim": 128,
456	    "linear_num_key_heads": 16,
457	    "linear_num_value_heads": 32,
458	    "linear_value_head_dim": 128,
459	    "rope_parameters": { "rope_theta": 10000.0, "partial_rotary_factor": 0.25 },
460	    "eos_token_id": 151645
461	  }
462	}"#,
463	        )
464	        .unwrap();
465	        Config35::from_file(dir.path().to_str().unwrap()).expect("fixture validates")
466	    }
467	
468	    fn test_geometry(rank: usize, world_size: usize) -> LocalGeometry {
469	        let tp = TensorParallelConfig::try_from((rank, world_size)).unwrap();
470	        LocalGeometry::try_new(&test_config(), tp).unwrap()
471	    }
472	
473	    #[test]
474	    fn linear_qkv_shard_segments_stitch_head_local_slices() {
475	        // test_config: k heads 16, v heads 32, head dim 128 → q=k=2048, v=4096.
476	        let config = test_config();
477	        let rank0 = linear_qkv_shard(&config, test_geometry(0, 2));
478	        assert_eq!(rank0.segments, [(0, 1024), (2048, 1024), (4096, 2048)]);
479	        assert_eq!(rank0.global, 8192, "q + k + v rows of the fused tensor");
480	
481	        let rank1 = linear_qkv_shard(&config, test_geometry(1, 2));
482	        assert_eq!(rank1.segments, [(1024, 1024), (3072, 1024), (6144, 2048)]);
483	        assert_eq!(rank1.global, rank0.global);
484	
485	        // Every rank's stitched rows tile [0, qkv) with no overlap: each
486	        // segment's local slices across ranks are contiguous and complete.
487	        for (r0, r1) in rank0.segments.iter().zip(rank1.segments.iter()) {
488	            assert_eq!(r0.1, r1.1);
489	            assert_eq!(r1.0, r0.0 + r0.1);
490	        }
491	    }
492	
493	    #[test]
494	    fn gated_q_shard_keeps_matching_q_and_gate_rows() {
495	        let config = test_config();
496	
497	        let rank0 = full_attention_gated_q_shard(&config, test_geometry(0, 2));
498	        assert_eq!(rank0.range, (0, 4096));
499	        assert_eq!(
500	            rank0.global, 8192,
501	            "16 heads x 256 head_dim, each head carrying q then gate"
502	        );
503	
504	        // Rank 1 starts at its own first head's q rows, not the flat midpoint.
505	        let rank1 = full_attention_gated_q_shard(&config, test_geometry(1, 2));
506	        assert_eq!(rank1.range, (4096, 4096));
507	        assert_eq!(rank1.global, rank0.global);
508	    }
509	}
