34	/// Raw-byte uploads through the same pinned double buffers used by the BF16
35	/// checkpoint loader. Source slices are concatenated into staging chunks.
36	pub struct ByteWeightStager {
37	    stream: Arc<cudarc::driver::CudaStream>,
38	    stager: WeightStager,
39	}
40	
41	impl ByteWeightStager {
42	    pub fn new(ctx: &DeviceContext) -> Result<Self> {
43	        Ok(Self {
44	            stream: ctx.stream.clone(),
45	            stager: WeightStager::new(ctx)?,
46	        })
47	    }
48	
49	    pub fn upload(&mut self, srcs: &[&[u8]], dst: &mut CudaSlice<u8>) -> Result<()> {
50	        let dst_at = staging::prepare_bytes(&self.stream, srcs, dst)?;
51	        // SAFETY: prepare_bytes validated the destination and concatenated size.
52	        unsafe { self.stager.upload_slices_at(srcs, dst_at) }
53	    }
54	}
