56	/// Load shard metadata. Returns (shard_file_paths, weight_map: tensor_name -> shard_index)
57	pub fn load_shard_info(model_path: &str) -> Result<(Vec<String>, HashMap<String, usize>)> {
58	    let single_path = format!("{}/model.safetensors", model_path);
59	    if std::path::Path::new(&single_path).exists() {
60	        return Ok((vec![single_path], HashMap::new()));
61	    }
62	
63	    let index_path = format!("{}/model.safetensors.index.json", model_path);
64	    let index_content = fs::read_to_string(&index_path)?;
65	    let index: serde_json::Value = serde_json::from_str(&index_content)?;
66	
67	    let weight_map_json = index["weight_map"]
68	        .as_object()
69	        .ok_or_else(|| anyhow::anyhow!("Invalid index.json: missing weight_map"))?;
70	
71	    let mut shard_files: Vec<String> = Vec::new();
72	    let mut file_to_idx: HashMap<String, usize> = HashMap::new();
73	    let mut weight_map: HashMap<String, usize> = HashMap::new();
74	
75	    for (tensor_name, shard_file_val) in weight_map_json {
76	        let shard_file = shard_file_val.as_str().unwrap().to_string();
77	        let idx = if let Some(&idx) = file_to_idx.get(&shard_file) {
78	            idx
79	        } else {
80	            let idx = shard_files.len();
81	            shard_files.push(format!("{model_path}/{shard_file}"));
82	            file_to_idx.insert(shard_file, idx);
83	            idx
84	        };
85	        weight_map.insert(tensor_name.clone(), idx);
86	    }
87	
88	    Ok((shard_files, weight_map))
89	}
