120	/// `RWF_NOWAIT` fails with `EAGAIN` for a page the kernel would have to fetch.
121	/// One page stands for the chunk, and any error counts as a miss.
122	fn chunk_looks_resident(file: &fs::File, off: u64) -> bool {
123	    let mut page = [0u8; 4096];
124	    let iov = libc::iovec {
125	        iov_base: page.as_mut_ptr().cast(),
126	        iov_len: page.len(),
127	    };
128	    // SAFETY: `iov` describes `page.len()` writable bytes that outlive the call.
129	    let got = unsafe {
130	        libc::preadv2(
131	            file.as_raw_fd(),
132	            &raw const iov,
133	            1,
134	            off as libc::off_t,
135	            libc::RWF_NOWAIT,
136	        )
137	    };
138	    got > 0
139	}
