294	/// Memory-map shard files and return the mmaps.
295	///
296	/// Typically chained with [`deserialize_shards`] to get `SafeTensors` views:
297	/// ```ignore
298	/// let mmaps = mmap_shards(&paths)?;
299	/// let shards = deserialize_shards(&mmaps)?;
300	/// ```
301	pub fn mmap_shards(shard_paths: &[String]) -> Result<Vec<Mmap>> {
302	    let mmaps: Vec<Mmap> = shard_paths
303	        .iter()
304	        .map(|p| {
305	            let file = fs::File::open(p)?;
306	            // SAFETY: we keep the Mmap alive for the duration of model loading,
307	            // and the file is not modified concurrently.
308	            unsafe { Mmap::map(&file) }
309	        })
310	        .collect::<std::io::Result<_>>()?;
311	
312	    let total_bytes: usize = mmaps.iter().map(|m| m.len()).sum();
313	    info!(
314	        "Memory-mapped {} shard(s) ({:.1} MB)",
315	        mmaps.len(),
316	        total_bytes as f64 / 1e6
317	    );
318	    Ok(mmaps)
319	}
