331	fn find_tensor<'a>(
332	    shards: &'a [SafeTensors<'a>],
333	    weight_map: &HashMap<String, usize>,
334	    name: &str,
335	) -> Result<safetensors::tensor::TensorView<'a>> {
336	    if let Some(&idx) = weight_map.get(name) {
337	        shards[idx]
338	            .tensor(name)
339	            .map_err(|e| anyhow::anyhow!("Failed to load tensor '{}': {}", name, e))
340	    } else {
341	        // Fallback: try all shards (single-file case)
342	        for shard in shards {
343	            if let Ok(t) = shard.tensor(name) {
344	                return Ok(t);
345	            }
346	        }
347	        Err(anyhow::anyhow!("Tensor '{}' not found in any shard", name))
348	    }
349	}
