396	/// Typed F32 payload with 1D-shape validation. A BF16 vector is widened
397	/// (bf16 → f32 is exact, and the reference implementations upcast these
398	/// vectors at the point of use). Aligned f32 payloads borrow zero-copy;
399	/// misaligned ones (legal in safetensors) decode little-endian into an owned
400	/// buffer, since a misaligned f32 view is UB.
401	#[allow(clippy::cast_ptr_alignment)]
402	fn tensor_f32_cow<'d>(
403	    tensor: &safetensors::tensor::TensorView<'d>,
404	    name: &str,
405	) -> Result<Cow<'d, [f32]>> {
406	    anyhow::ensure!(
407	        tensor.shape().len() == 1,
408	        "Tensor '{name}': expected 1D shape, got {:?}",
409	        tensor.shape()
410	    );
411	    if tensor.dtype() == Dtype::BF16 {
412	        let bits = tensor_bf16_cow(tensor, name)?;
413	        return Ok(Cow::Owned(bits.iter().map(|&b| f32::from(b)).collect()));
414	    }
415	    anyhow::ensure!(
416	        tensor.dtype() == Dtype::F32,
417	        "Tensor '{name}': expected dtype F32 or BF16, got {:?}",
418	        tensor.dtype()
419	    );
420	    let data = tensor.data();
421	    anyhow::ensure!(
422	        data.len().is_multiple_of(std::mem::size_of::<f32>()),
423	        "Tensor '{name}': {} bytes is not a whole number of f32 elements",
424	        data.len()
425	    );
426	    if (data.as_ptr() as usize).is_multiple_of(std::mem::align_of::<f32>()) {
427	        // SAFETY: alignment checked; any bit pattern is a valid f32.
428	        Ok(Cow::Borrowed(unsafe {
429	            std::slice::from_raw_parts(
430	                data.as_ptr().cast::<f32>(),
431	                data.len() / std::mem::size_of::<f32>(),
432	            )
433	        }))
434	    } else {
435	        Ok(Cow::Owned(
436	            data.as_chunks::<4>()
437	                .0
438	                .iter()
439	                .map(|&b| f32::from_le_bytes(b))
440	                .collect(),
441	        ))
442	    }
443	}
