646	    /// Row-concatenation of `parts`, each a validated row range of its
647	    /// source tensor; all sources must have exactly `cols` columns.
648	    pub fn fused_rows(&mut self, cols: usize, parts: &[FusedPart]) -> Result<SlotId> {
649	        self.ensure_recording()?;
650	        anyhow::ensure!(!parts.is_empty(), "fused load needs at least one part");
651	        let mut total_rows = 0usize;
652	        let mut srcs = Vec::with_capacity(parts.len());
653	        for part in parts {
654	            let name = part.name;
655	            let full = self.tensor_2d(name, part.src_rows, cols)?;
656	            anyhow::ensure!(
657	                part.row_offset
658	                    .checked_add(part.rows)
659	                    .is_some_and(|end| end <= part.src_rows),
660	                "row range out of bounds for '{name}': row_offset={} rows={} total_rows={}",
661	                part.row_offset,
662	                part.rows,
663	                part.src_rows
664	            );
665	            let elem = std::mem::size_of::<bf16>();
666	            srcs.push(
667	                &full[part.row_offset * cols * elem..(part.row_offset + part.rows) * cols * elem],
668	            );
669	            total_rows += part.rows;
670	        }
671	        let mut data = self.alloc_timed(total_rows * cols, parts[0].name)?;
672	        let mut dst_offset = 0;
673	        for src in srcs {
674	            let dst_at = staging::prepare(&self.ctx.stream, src, &mut data, dst_offset)?;
675	            self.pending.push(PendingUpload::Contiguous { src, dst_at });
676	            dst_offset += src.len() / std::mem::size_of::<bf16>();
677	        }
678	        Ok(self.push_slot(data, total_rows, cols))
679	    }
680	
681	    /// `take` columns starting at `col_offset` of a source tensor validated
682	    /// to exactly `src_rows` x `src_cols` before anything is allocated.
683	    pub fn col_shard(
684	        &mut self,
685	        name: &str,
686	        src_rows: usize,
687	        src_cols: usize,
688	        col_offset: usize,
689	        take: usize,
690	    ) -> Result<SlotId> {
691	        self.ensure_recording()?;
692	        let full = self.tensor_2d(name, src_rows, src_cols)?;
693	        anyhow::ensure!(
694	            col_offset
695	                .checked_add(take)
696	                .is_some_and(|end| end <= src_cols),
697	            "col range out of bounds for '{name}': col_offset={col_offset} take={take} total_cols={src_cols}"
698	        );
699	        let mut data = self.alloc_timed(src_rows * take, name)?;
700	        let plan = staging::prepare_cols(
701	            &self.ctx.stream,
702	            full,
703	            src_cols,
704	            col_offset,
705	            take,
706	            &mut data,
707	        )?;
708	        self.pending
709	            .push(PendingUpload::ColShard { src: full, plan });
710	        Ok(self.push_slot(data, src_rows, take))
711	    }
712	
713	    /// Small tensors; uploaded as plain pageable copies.
714	    pub fn vector(&mut self, name: &str, len: usize) -> Result<VecSlotId> {
715	        self.ensure_recording()?;
716	        let tensor = find_tensor(self.shards, self.weight_map, name)?;
717	        let shape = tensor.shape();
718	        anyhow::ensure!(
719	            shape.len() == 1 && shape[0] == len,
720	            "Tensor '{name}' has shape {shape:?}, config expects [{len}]"
721	        );
722	        let src = tensor_bf16_cow(&tensor, name)?;
723	        let mut data = self.alloc_timed(len, name)?;
724	        let dst_at = staging::prepare(&self.ctx.stream, bf16_bytes(&src), &mut data, 0)?;
725	        self.pending.push(PendingUpload::Vector { src, dst_at });
726	        self.vec_slots.push(VecSlot {
727	            data: Some(data),
728	            len,
729	        });
730	        Ok(VecSlotId(self.vec_slots.len() - 1))
731	    }
732	
733	    /// Redeems a recorded vector after a successful [`Self::finish`].
734	    pub fn take_vec(&mut self, slot: VecSlotId) -> DeviceVec {
735	        assert!(self.finished, "take before successful finish");
736	        let slot = &mut self.vec_slots[slot.0];
737	        DeviceVec {
738	            data: slot.data.take().expect("slot already taken"),
739	            len: slot.len,
740	        }
741	    }
742	}
