744	impl Drop for StagedWeightLoader<'_> {
745	    // Second layer only: the soundness boundary closes inside `finish`.
746	    fn drop(&mut self) {
747	        if self.failed {
748	            staging::drain_or_abort(&self.ctx.stream, "staged loader drop");
749	        }
750	    }
751	}
