763	pub fn load_tensor_2d(
764	    ctx: &DeviceContext,
765	    shards: &[SafeTensors],
766	    weight_map: &HashMap<String, usize>,
767	    name: &str,
768	    rows: usize,
769	    cols: usize,
770	) -> Result<DeviceMatrix> {
771	    let tensor = find_tensor(shards, weight_map, name)?;
772	    let shape = tensor.shape();
773	    anyhow::ensure!(
774	        shape.len() == 2 && shape[0] == rows && shape[1] == cols,
775	        "Tensor '{name}' has shape {shape:?}, expected [{rows}, {cols}]"
776	    );
777	    DeviceMatrix::from_safetensors(ctx, tensor.data(), rows, cols)
778	}
779	
780	fn tensor_2d_dims(
781	    tensor: &safetensors::tensor::TensorView<'_>,
782	    name: &str,
783	) -> Result<(usize, usize)> {
784	    let shape = tensor.shape();
785	    anyhow::ensure!(
786	        shape.len() == 2,
787	        "Tensor '{name}' expected 2D, got shape {shape:?}"
788	    );
789	    Ok((shape[0], shape[1]))
790	}
