792	fn check_row_range(name: &str, row_offset: usize, rows: usize, total_rows: usize) -> Result<()> {
793	    anyhow::ensure!(
794	        row_offset + rows <= total_rows,
795	        "2D row range out of bounds for '{name}': row_offset={row_offset} rows={rows} total_rows={total_rows}"
796	    );
797	    Ok(())
798	}
799	
800	/// Reject a checkpoint whose full tensor shape disagrees with the config the
801	/// shard ranges were derived from, before any slice of it is trusted.
802	fn ensure_global_shape(name: &str, actual: (usize, usize), expected: (usize, usize)) -> Result<()> {
803	    anyhow::ensure!(
804	        actual == expected,
805	        "Tensor '{name}' has shape [{}, {}], expected [{}, {}]",
806	        actual.0,
807	        actual.1,
808	        expected.0,
809	        expected.1
810	    );
811	    Ok(())
812	}
