814	/// Load one row range of a row-parallel 2D tensor. `global` is the
815	/// config-derived `(rows, cols)` of the full unsharded tensor; the header must
816	/// match it before the slice is taken.
817	pub fn load_tensor_2d_row_shard(
818	    ctx: &DeviceContext,
819	    shards: &[SafeTensors],
820	    weight_map: &HashMap<String, usize>,
821	    name: &str,
822	    row_offset: usize,
823	    rows: usize,
824	    global: (usize, usize),
825	) -> Result<DeviceMatrix> {
826	    let tensor = find_tensor(shards, weight_map, name)?;
827	    let (total_rows, cols) = tensor_2d_dims(&tensor, name)?;
828	    ensure_global_shape(name, (total_rows, cols), global)?;
829	    check_row_range(name, row_offset, rows, total_rows)?;
830	    let elems = tensor_bf16_cow(&tensor, name)?;
831	    let start = row_offset * cols;
832	    let end = (row_offset + rows) * cols;
833	    DeviceMatrix::from_host(ctx, &elems[start..end], rows, cols)
834	}
835	
836	fn gather_cols(
837	    elems: &[bf16],
838	    rows: usize,
839	    total_cols: usize,
840	    col_offset: usize,
841	    take: usize,
842	) -> Vec<bf16> {
843	    let mut host = vec![bf16::ZERO; rows * take];
844	    for row in 0..rows {
845	        let src = row * total_cols + col_offset;
846	        let dst = row * take;
847	        host[dst..dst + take].copy_from_slice(&elems[src..src + take]);
848	    }
849	    host
850	}
851	
852	/// Load one column range of a column-parallel 2D tensor. `global` is the
853	/// config-derived `(rows, cols)` of the full unsharded tensor; the header must
854	/// match it before the slice is taken.
855	pub fn load_tensor_2d_col_shard(
856	    ctx: &DeviceContext,
857	    shards: &[SafeTensors],
858	    weight_map: &HashMap<String, usize>,
859	    name: &str,
860	    col_offset: usize,
861	    cols: usize,
862	    global: (usize, usize),
863	) -> Result<DeviceMatrix> {
864	    let tensor = find_tensor(shards, weight_map, name)?;
865	    let (rows, total_cols) = tensor_2d_dims(&tensor, name)?;
866	    ensure_global_shape(name, (rows, total_cols), global)?;
867	    if col_offset + cols > total_cols {
868	        return Err(anyhow::anyhow!(
869	            "2D col shard out of bounds for '{}': col_offset={} cols={} total_cols={}",
870	            name,
871	            col_offset,
872	            cols,
873	            total_cols
874	        ));
875	    }
876	    let elems = tensor_bf16_cow(&tensor, name)?;
877	    let host = gather_cols(&elems, rows, total_cols, col_offset, cols);
878	    DeviceMatrix::from_host(ctx, &host, rows, cols)
879	}
880	
881	/// Load a 2D tensor assembled from multiple row ranges of one source tensor,
882	/// stitched in `ranges` order: each entry is (row_offset, rows). `global` is
883	/// the config-derived `(rows, cols)` of the full source tensor; the header
884	/// must match it before any slice is taken.
885	pub fn load_tensor_2d_row_stitch(
886	    ctx: &DeviceContext,
887	    shards: &[SafeTensors],
888	    weight_map: &HashMap<String, usize>,
889	    name: &str,
890	    ranges: &[(usize, usize)],
891	    global: (usize, usize),
892	) -> Result<DeviceMatrix> {
893	    let tensor = find_tensor(shards, weight_map, name)?;
894	    let (total_rows, cols) = tensor_2d_dims(&tensor, name)?;
895	    ensure_global_shape(name, (total_rows, cols), global)?;
896	    let mut total = 0usize;
897	    for &(row_offset, rows) in ranges {
898	        check_row_range(name, row_offset, rows, total_rows)?;
899	        total += rows;
900	    }
901	    let elems = tensor_bf16_cow(&tensor, name)?;
902	    let mut host = Vec::with_capacity(total * cols);
903	    for &(row_offset, rows) in ranges {
904	        let start = row_offset * cols;
905	        host.extend_from_slice(&elems[start..start + rows * cols]);
906	    }
907	    DeviceMatrix::from_host(ctx, &host, total, cols)
908	}
909	
910	/// Load a 1D BF16 tensor assembled from multiple element ranges of one source
911	/// tensor, stitched in `ranges` order: each entry is (offset, len).
912	pub fn load_tensor_1d_stitch(
913	    ctx: &DeviceContext,
914	    shards: &[SafeTensors],
915	    weight_map: &HashMap<String, usize>,
916	    name: &str,
917	    ranges: &[(usize, usize)],
918	) -> Result<DeviceVec> {
919	    let tensor = find_tensor(shards, weight_map, name)?;
920	    let elems = tensor_bf16_cow(&tensor, name)?;
921	    let mut total = 0usize;
922	    for &(offset, len) in ranges {
923	        if offset + len > elems.len() {
924	            return Err(anyhow::anyhow!(
925	                "1D stitch out of bounds for '{}': offset={} len={} total_len={}",
926	                name,
927	                offset,
928	                len,
929	                elems.len()
930	            ));
931	        }
932	        total += len;
933	    }
934	    let mut host = Vec::with_capacity(total);
935	    for &(offset, len) in ranges {
936	        host.extend_from_slice(&elems[offset..offset + len]);
937	    }
938	    DeviceVec::from_host(ctx, &host)
939	}
