941	/// Load a 1D F32 element range to GPU (tensor-parallel shard of a 1D weight).
942	pub fn load_tensor_1d_f32_shard(
943	    ctx: &DeviceContext,
944	    shards: &[SafeTensors],
945	    weight_map: &HashMap<String, usize>,
946	    name: &str,
