964	/// Load a 1D F32 tensor to GPU as CudaSlice<f32>; a BF16 vector is widened
965	/// (see [`tensor_f32_cow`]). For weights stored in float32 (e.g., A_log,
966	/// norm.weight in linear attention).
967	pub fn load_tensor_1d_f32(
968	    ctx: &DeviceContext,
969	    shards: &[SafeTensors],
970	    weight_map: &HashMap<String, usize>,
971	    name: &str,
972	) -> Result<CudaSlice<f32>> {
973	    let tensor = find_tensor(shards, weight_map, name)?;
974	    let elems = tensor_f32_cow(&tensor, name)?;
975	    upload_f32(ctx, name, elems.as_ref())
976	}
