978	fn upload_f32(ctx: &DeviceContext, name: &str, host: &[f32]) -> Result<CudaSlice<f32>> {
979	    ctx.stream
980	        .clone_htod(host)
981	        .map_err(|e| anyhow::anyhow!("H2D copy failed for '{name}': {e}"))
982	}
