984	/// Load a 1D I64 tensor into a host `Vec<i64>`.
985	///
986	/// For small integer lookup tables that live on the host (e.g. EAGLE-3's `d2t`
987	/// draft→target vocab offset map), not weights destined for a GEMM.
988	pub fn load_tensor_i64_host(
989	    shards: &[SafeTensors],
990	    weight_map: &HashMap<String, usize>,
991	    name: &str,
992	) -> Result<Vec<i64>> {
993	    let tensor = find_tensor(shards, weight_map, name)?;
994	
995	    if tensor.dtype() != Dtype::I64 {
996	        return Err(anyhow::anyhow!(
997	            "I64 tensor '{}': expected dtype I64, got {:?}",
998	            name,
999	            tensor.dtype()
1000	        ));
1001	    }
1002	    if tensor.shape().len() != 1 {
1003	        return Err(anyhow::anyhow!(
1004	            "I64 tensor '{}': expected 1D, got shape {:?}",
1005	            name,
1006	            tensor.shape()
1007	        ));
1008	    }
1009	    let data = tensor.data();
1010	    if data.len() % 8 != 0 {
1011	        return Err(anyhow::anyhow!(
1012	            "I64 tensor '{}': data length {} not multiple of 8",
1013	            name,
1014	            data.len()
1015	        ));
1016	    }
1017	    Ok(data
1018	        .as_chunks::<8>()
1019	        .0
1020	        .iter()
1021	        .map(|&b| i64::from_le_bytes(b))
1022	        .collect())
1023	}
1024	
1025	/// Load a 1D BOOL tensor into a host `Vec<bool>` (safetensors stores BOOL as one
1026	/// byte per element, `0`/`1`). For mask tables like EAGLE-3's `t2d`.
1027	pub fn load_tensor_bool_host(
1028	    shards: &[SafeTensors],
1029	    weight_map: &HashMap<String, usize>,
1030	    name: &str,
1031	) -> Result<Vec<bool>> {
1032	    let tensor = find_tensor(shards, weight_map, name)?;
1033	    if tensor.dtype() != Dtype::BOOL {
1034	        return Err(anyhow::anyhow!(
1035	            "BOOL tensor '{}': expected dtype BOOL, got {:?}",
1036	            name,
1037	            tensor.dtype()
1038	        ));
1039	    }
1040	    if tensor.shape().len() != 1 {
1041	        return Err(anyhow::anyhow!(
1042	            "BOOL tensor '{}': expected 1D, got shape {:?}",
1043	            name,
1044	            tensor.shape()
1045	        ));
1046	    }
1047	    Ok(tensor.data().iter().map(|&b| b != 0).collect())
1048	}
1049	
1050	/// Load shard info with fixup for mismatched shard filenames in index.json.
1051	///
1052	/// Some models (e.g., Qwen3.5) have index.json with shard filenames like
1053	/// `model.safetensors-00001-of-00002.safetensors` while actual files are
1054	/// `model-00001-of-00002.safetensors`. This function detects and fixes that.
1055	pub fn load_shard_info_fixed(model_path: &str) -> Result<(Vec<String>, HashMap<String, usize>)> {
1056	    let (mut shard_files, weight_map) = load_shard_info(model_path)?;
1057	
1058	    for path in &mut shard_files {
1059	        if !std::path::Path::new(path).exists() {
1060	            // Try replacing "model.safetensors-" with "model-" in filename
1061	            let filename = std::path::Path::new(path)
1062	                .file_name()
1063	                .unwrap()
1064	                .to_str()
1065	                .unwrap();
1066	            if let Some(rest) = filename.strip_prefix("model.safetensors-") {
1067	                let fixed = format!("{}/model-{}", model_path, rest);
1068	                if std::path::Path::new(&fixed).exists() {
1069	                    log::info!(
1070	                        "Fixed shard path: {} -> {}",
1071	                        filename,
1072	                        std::path::Path::new(&fixed)
1073	                            .file_name()
1074	                            .unwrap()
1075	                            .to_str()
1076	                            .unwrap()
1077	                    );
1078	                    *path = fixed;
1079	                    continue;
1080	                }
1081	            }
1082	            return Err(anyhow::anyhow!("Shard file not found: {}", path));
1083	        }
1084	    }
1085	
1086	    Ok((shard_files, weight_map))
1087	}
