1089	#[cfg(test)]
1090	mod tests {
1091	    use std::borrow::Cow;
1092	
1093	    use safetensors::Dtype;
1094	    use safetensors::tensor::TensorView;
1095	
1096	    use super::tensor_bf16_cow;
1097	    use super::tensor_f32_cow;
1098	
1099	    #[test]
1100	    fn tensor_f32_cow_borrows_aligned_and_decodes_unaligned() {
1101	        let vals: [u32; 4] = [0x3f80_0000, 0x0000_0001, 0xbf12_3456, 0x7f80_0001];
1102	        let mut bytes = vec![0u8; vals.len() * 4 + 3];
1103	        // A Vec<u8> base has no alignment guarantee; derive both offsets from
1104	        // the actual address so each branch is forced deterministically.
1105	        let base = bytes.as_ptr() as usize;
1106	        let aligned_off = base.next_multiple_of(4) - base;
1107	        for (off, expect_borrowed) in [(aligned_off, true), (aligned_off + 1, false)] {
1108	            for (i, v) in vals.iter().enumerate() {
1109	                bytes[off + i * 4..off + i * 4 + 4].copy_from_slice(&v.to_le_bytes());
1110	            }
1111	            let view = TensorView::new(
1112	                Dtype::F32,
1113	                vec![vals.len()],
1114	                &bytes[off..off + vals.len() * 4],
1115	            )
1116	            .unwrap();
1117	            let cow = tensor_f32_cow(&view, "w").unwrap();
1118	            assert_eq!(
1119	                matches!(cow, Cow::Borrowed(_)),
1120	                expect_borrowed,
1121	                "off={off}"
1122	            );
1123	            let got: Vec<u32> = cow.iter().map(|f| f.to_bits()).collect();
1124	            assert_eq!(got, vals, "off={off}");
1125	        }
1126	    }
1127	
1128	    #[test]
1129	    fn tensor_f32_cow_accepts_bf16_and_rejects_invalid_dtype_or_rank() {
1130	        let bytes = vec![0u8; 8];
1131	        let bf16_view = TensorView::new(Dtype::BF16, vec![4], &bytes).unwrap();
1132	        assert!(tensor_f32_cow(&bf16_view, "w").is_ok());
1133	        let f16_view = TensorView::new(Dtype::F16, vec![4], &bytes).unwrap();
1134	        assert!(tensor_f32_cow(&f16_view, "w").is_err());
1135	        let f32_2d_view = TensorView::new(Dtype::F32, vec![2, 1], &bytes).unwrap();
1136	        assert!(tensor_f32_cow(&f32_2d_view, "w").is_err());
1137	        let bf16_2d_view = TensorView::new(Dtype::BF16, vec![2, 2], &bytes).unwrap();
1138	        assert!(tensor_f32_cow(&bf16_2d_view, "w").is_err());
1139	    }
1140	
1141	    #[test]
1142	    fn tensor_bf16_cow_borrows_aligned_and_decodes_unaligned() {
1143	        let vals: [u16; 4] = [0x3f80, 0x0001, 0xbf12, 0x7fff];
1144	        let mut bytes = vec![0u8; vals.len() * 2 + 3];
1145	        // A Vec<u8> base has no alignment guarantee; derive both offsets from
1146	        // the actual address so each branch is forced deterministically.
1147	        let base = bytes.as_ptr() as usize;
1148	        let aligned_off = base.next_multiple_of(2) - base;
1149	        for (off, expect_borrowed) in [(aligned_off, true), (aligned_off + 1, false)] {
1150	            for (i, v) in vals.iter().enumerate() {
1151	                bytes[off + i * 2..off + i * 2 + 2].copy_from_slice(&v.to_le_bytes());
1152	            }
1153	            let view = TensorView::new(
1154	                Dtype::BF16,
1155	                vec![vals.len()],
1156	                &bytes[off..off + vals.len() * 2],
1157	            )
1158	            .unwrap();
1159	            let cow = tensor_bf16_cow(&view, "w").unwrap();
1160	            assert_eq!(
1161	                matches!(cow, Cow::Borrowed(_)),
1162	                expect_borrowed,
1163	                "off={off}"
1164	            );
1165	            let got: Vec<u16> = cow.iter().map(|b| b.to_bits()).collect();
1166	            assert_eq!(got, vals, "off={off}");
1167	        }
1168	    }
1169	}
